        model = _rr_to_model(rr)
        records.append({"name": model["name"], "type": model["type"],
                        "ttl": model["ttl"], "rdata": model["rdata"].hex()})
    return {"version": 2, "origin": _labels_to_name(origin_labels),
            "class": zone_class, "records": records}


